INSERT INTO chapter_creation_idempotency (
    owner_id, project_id, idempotency_key, request_fingerprint
) VALUES (
    #{ownerId}, #{projectId}, #{idempotencyKey}, #{requestFingerprint}
) ON CONFLICT (owner_id, project_id, idempotency_key)
    DO UPDATE SET idempotency_key = EXCLUDED.idempotency_key
RETURNING id, owner_id, project_id, idempotency_key, request_fingerprint, chapter_id
